create table public.shared_notes(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id),title text not null check(length(trim(title)) between 1 and 120),content text not null default '' check(length(content)<=20000),created_by uuid not null references public.profiles(id),updated_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.saved_links(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,conversation_id uuid not null references public.conversations(id),message_id uuid references public.messages(id) on delete cascade,url text not null check(url ~ '^https?://' and length(url)<=2048),title text not null check(length(title)<=200),created_at timestamptz not null default now(),unique(user_id,url));
create index notes_conversation on public.shared_notes(conversation_id);
create index notes_creator on public.shared_notes(created_by);
create index notes_updater on public.shared_notes(updated_by);
create index links_conversation on public.saved_links(conversation_id);
create index links_message on public.saved_links(message_id);
alter table public.shared_notes enable row level security;
alter table public.saved_links enable row level security;
create policy notes_read on public.shared_notes for select to authenticated using(nanba_private.member(conversation_id));
create policy notes_create on public.shared_notes for insert to authenticated with check(created_by=auth.uid() and updated_by=auth.uid() and nanba_private.member(conversation_id));
create policy notes_update on public.shared_notes for update to authenticated using(nanba_private.member(conversation_id)) with check(updated_by=auth.uid() and nanba_private.member(conversation_id));
create policy notes_delete on public.shared_notes for delete to authenticated using(nanba_private.member(conversation_id));
create policy links_read on public.saved_links for select to authenticated using(user_id=auth.uid() and nanba_private.member(conversation_id));
create policy links_create on public.saved_links for insert to authenticated with check(user_id=auth.uid() and nanba_private.member(conversation_id) and (message_id is null or exists(select 1 from public.messages where id=message_id and conversation_id=saved_links.conversation_id)));
create policy links_delete on public.saved_links for delete to authenticated using(user_id=auth.uid() and nanba_private.member(conversation_id));
revoke all on public.shared_notes,public.saved_links from anon,authenticated;
grant select,insert,delete on public.shared_notes,public.saved_links to authenticated;
grant update(title,content,updated_by) on public.shared_notes to authenticated;
create function nanba_private.touch_note() returns trigger language plpgsql set search_path='' as $$begin new.updated_at=now();return new;end$$;
create trigger touch_note before update on public.shared_notes for each row execute function nanba_private.touch_note();
alter publication supabase_realtime add table public.shared_notes;
